/**
 * ANALYST UD — evidence, not product code. Read-only investigation of Kent's
 * report that "the ? to open the hotkeys panel is not working".
 *
 * Three screens exist in this app: the launchpad (App.tsx), the stored map
 * (MapScreen.tsx) and the map building itself (stream/GenerationScreen.tsx).
 * This file presses `?` on the launchpad and on the generation screen and asks
 * whether the sheet of every key appears.
 *
 * Run it with the config beside it:
 *   cd frontend && npx vitest run --config \
 *     /Users/kentgang/git3/katalyst/plans/analysis/scripts/ux-round/D/vitest.qkey.ts
 *
 * The `node_modules` symbolic link in this directory points at `frontend/node_modules`
 * and is what lets a file outside `frontend/` resolve `@testing-library/react`. Nothing
 * in the repository is changed by any of this.
 *
 * Result on `main` at feda9ac: all four pass. `?` opens the sheet on the stored map and
 * on neither of the other two screens.
 */

import { fireEvent, render, screen } from "@testing-library/react";
import { beforeAll, describe, expect, it } from "vitest";
import { App } from "../../../../../frontend/src/App";
import { GenerationScreen } from "../../../../../frontend/src/stream/GenerationScreen";
import { waitingFor } from "../../../../../frontend/src/stream/growth";
import { MapScreen } from "../../../../../frontend/src/components/MapScreen";
import { aWorld } from "../../../../../frontend/src/test/aMap";
import type { TheRun } from "../../../../../frontend/src/stream/theRun";

beforeAll(() => {
  // React Flow measures the page; jsdom has no measuring at all.
  globalThis.ResizeObserver ??= class {
    observe() {}
    unobserve() {}
    disconnect() {}
  } as unknown as typeof ResizeObserver;
  globalThis.DOMMatrixReadOnly ??= class {
    m22 = 1;
    constructor(_t?: string) {}
  } as unknown as typeof DOMMatrixReadOnly;
});

/** A run that has been asked for and has said nothing yet. Nothing is fetched. */
function aRunThatHasSaidNothing(): TheRun {
  const growth = waitingFor("The Strait of Hormuz is going to open next week.", null);
  const where = { growth, saying: "" };
  return {
    asked: { hypothesis: growth.world.title, target: null, belief: null },
    press: "press-1",
    now: () => where,
    watch: () => () => {},
    letGo: () => {},
  };
}

describe("the ? key, screen by screen", () => {
  it("the generation screen: ? does nothing", () => {
    render(
      <GenerationScreen
        run={aRunThatHasSaidNothing()}
        replaying={true}
        onRunAgain={() => {}}
        onLeave={() => {}}
      />,
    );
    // The top bar's own control says the key works.
    expect(screen.getByRole("button", { name: /Every key/ })).toBeInTheDocument();
    fireEvent.keyDown(document.body, { key: "?", code: "Slash", shiftKey: true });
    // And the sheet is not there.
    expect(screen.queryByText(/Tiles do not move/)).toBeNull();
  });

  it("the generation screen: the top-bar control DOES open it", () => {
    render(
      <GenerationScreen
        run={aRunThatHasSaidNothing()}
        replaying={true}
        onRunAgain={() => {}}
        onLeave={() => {}}
      />,
    );
    fireEvent.click(screen.getByRole("button", { name: /Every key/ }));
    expect(screen.getByText(/Tiles do not move/)).toBeInTheDocument();
  });

  it("the stored map: ? DOES open it — the control that proves the press lands", () => {
    render(
      <MapScreen
        base={aWorld()}
        branches={[]}
        source={
          {
            readWorld: () => Promise.resolve(aWorld()),
            readBundle: () => Promise.resolve({ base: aWorld(), branches: [] }),
          } as never
        }
        insteadOfTheEngine={null}
        onLeave={() => {}}
      />,
    );
    fireEvent.keyDown(document.body, { key: "?", code: "Slash", shiftKey: true });
    expect(screen.getByText(/Tiles do not move/)).toBeInTheDocument();
  });

  it("the launchpad: ? does nothing", () => {
    render(
      <App
        listExamples={() => Promise.resolve([])}
      />,
    );
    fireEvent.keyDown(document.body, { key: "?", code: "Slash", shiftKey: true });
    expect(screen.queryByText(/Tiles do not move/)).toBeNull();
  });
});

