275	/** The screen. */
276	export function App({
277	  source = DEFAULT_SOURCE,
278	  fallback = FALLBACK_SOURCE,
279	  listExamples = readExampleList,
280	}: AppProps = {}) {
281	  const health = useAnswer(readHealth);
282	  const readiness = useAnswer(askReadiness);
283	  const about = useAnswer(readAbout);
284	  const examples = useAnswer(listExamples);
285	
286	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
287	  const [using, setUsing] = useState<WorldSource>(source);
288	
289	  const open = useCallback(
290	    (id: string) => {
291	      setScreen({ at: "opening", id });
292	      /**
293	       * The world and the map's own branches, together: the world is what gets
294	       * drawn, and the branches are the edits somebody already made to it, which
295	       * the panel lists and the diff view folds on.
296	       *
297	       * @param from Where to ask.
298	       */
299	      const ask = (from: WorldSource) =>
300	        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);
301	
302	      ask(source).then(
303	        ([world, bundle]) => {
304	          setUsing(source);
305	          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
306	        },
307	        (failure: unknown) => {
308	          // The engine could not answer. Rather than a blank screen, the stored
309	          // example — and a line under the map saying, in the failure's own
310	          // words, that these are not computed numbers.
311	          ask(fallback).then(
312	            ([world, bundle]) => {
313	              setUsing(fallback);
314	              setScreen({
315	                at: "map",
316	                world,
317	                branches: branchesOf(bundle),
318	                insteadOfTheEngine: insteadOfTheEngine(asOneSentence(failure)),
319	              });
320	            },
321	            // Neither answered, which means the server itself is not there. That
322	            // is one sentence on the page, and a way back to the launchpad.
323	            (alsoFailed: unknown) =>
324	              setScreen({ at: "failed", id, reason: asOneSentence(alsoFailed) }),
325	          );
326	        },
327	      );
328	    },
329	    [source, fallback],
330	  );
331	
332	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
333	
334	  /**
335	   * Build a map from a sentence, and watch it arrive.
336	   *
337	   * **The request goes from here**, inside the press. Not from a render and not
338	   * from an effect: an effect runs twice in development by design, and this is
339	   * the one request in the product where running twice means paying twice.
340	   */
341	  const build = useCallback((asked: Asked) => {
342	    setScreen({ at: "growing", run: askForAMap(asked) });
343	  }, []);
344	
345	  /**
346	   * Leave a generation: let go of it first, then go back.
347	   *
348	   * Letting go is what stops the spending — the route checks whether the client
349	   * is still there before its next model call — and it is done here, in the
350	   * press, rather than when the screen unmounts, for the same reason the run is
351	   * started in a press: a development-mode unmount would stop a run nobody left.
352	   */
