/*
 * The shortcuts sheet.
 *
 * Sits over the map at its bottom right, over nothing else: no scrim, nothing
 * dimmed, nothing to dismiss but Escape. The keys are set in the fixed-width
 * face and lined up in a column, so the sheet reads as a reference card rather
 * than as a dialog.
 */

.sheet {
  position: absolute;
  right: var(--space-4);
  bottom: var(--space-4);
  z-index: 40;
  display: grid;
  row-gap: var(--space-1);
  width: min(480px, calc(100% - var(--space-6)));
  max-height: calc(100% - var(--space-6));
  padding: var(--space-2);
  border: 1px solid var(--hairline);
  border-radius: var(--radius);
  background: var(--surface-raised);
  overflow-y: auto;
}

.sheet__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-1);

